export const PYTHON_DIFY_TOOL_WORKER = String.raw`#!/usr/bin/env python3
"""Minimal Dify Tool compatibility worker generated by dsh-dify-migrator.

The DSH host owns discovery, credentials, timeouts and audit. This worker only
adapts the public Dify Tool _invoke contract to one JSON request/response.
"""
from __future__ import annotations

import importlib.util
import inspect
import json
import pathlib
import sys
import types
from dataclasses import asdict, dataclass
from typing import Any


@dataclass
class ToolInvokeMessage:
    type: str
    value: Any
    meta: dict[str, Any] | None = None


class Tool:
    def __init__(self, runtime: Any | None = None, **_: Any) -> None:
        self.runtime = runtime or types.SimpleNamespace(credentials={})

    def create_text_message(self, text: Any) -> ToolInvokeMessage:
        return ToolInvokeMessage("text", str(text))

    def create_json_message(self, value: Any) -> ToolInvokeMessage:
        return ToolInvokeMessage("json", value)

    def create_variable_message(self, variable_name: str, variable_value: Any) -> ToolInvokeMessage:
        return ToolInvokeMessage("variable", variable_value, {"name": variable_name})

    def create_blob_message(self, blob: bytes, meta: dict[str, Any] | None = None) -> ToolInvokeMessage:
        import base64
        return ToolInvokeMessage("blob", base64.b64encode(blob).decode("ascii"), meta)

    def create_link_message(self, link: str) -> ToolInvokeMessage:
        return ToolInvokeMessage("link", link)

    def create_image_message(self, image: str) -> ToolInvokeMessage:
        return ToolInvokeMessage("image", image)


def _install_dify_shim() -> None:
    plugin = types.ModuleType("dify_plugin")
    entities = types.ModuleType("dify_plugin.entities")
    tool = types.ModuleType("dify_plugin.entities.tool")
    tool.Tool = Tool
    tool.ToolInvokeMessage = ToolInvokeMessage
    plugin.Tool = Tool
    plugin.entities = entities
    entities.tool = tool
    sys.modules["dify_plugin"] = plugin
    sys.modules["dify_plugin.entities"] = entities
    sys.modules["dify_plugin.entities.tool"] = tool


def _load_tool(path: pathlib.Path) -> type[Tool]:
    spec = importlib.util.spec_from_file_location("dsh_migrated_tool", path)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"cannot load tool implementation: {path}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    candidates = [value for value in vars(module).values()
                  if inspect.isclass(value) and value is not Tool and issubclass(value, Tool)]
    if not candidates:
        raise RuntimeError(f"no Dify Tool subclass found in {path}")
    return candidates[0]


def _message(value: Any) -> dict[str, Any]:
    if isinstance(value, ToolInvokeMessage):
        return asdict(value)
    if hasattr(value, "model_dump"):
        dumped = value.model_dump(mode="json")
        return dumped if isinstance(dumped, dict) else {"type": "json", "value": dumped}
    if isinstance(value, dict):
        return value if "type" in value else {"type": "json", "value": value}
    return {"type": "text", "value": str(value)}


def main() -> None:
    _install_dify_shim()
    request = json.load(sys.stdin)
    payload = pathlib.Path(request["payloadPath"]).resolve()
    sys.path.insert(0, str(payload))
    implementation = (payload / request["implementationPath"]).resolve()
    if payload not in implementation.parents:
        raise RuntimeError("implementation path escapes package payload")
    tool_type = _load_tool(implementation)
    runtime = types.SimpleNamespace(credentials=request.get("credentials") or {})
    instance = tool_type(runtime=runtime)
    result = instance._invoke(tool_parameters=request.get("arguments") or {})
    messages = [_message(item) for item in result]
    json.dump({"ok": True, "messages": messages}, sys.stdout, ensure_ascii=False)


if __name__ == "__main__":
    try:
        main()
    except Exception as error:
        json.dump({"ok": False, "error": {"type": type(error).__name__, "message": str(error)}}, sys.stdout, ensure_ascii=False)
        sys.exit(1)
`
